   373  int SSL_CTX_use_PrivateKey(SSL_CTX *ctx, EVP_PKEY *pkey) {
   374    if (pkey == NULL) {
   375      OPENSSL_PUT_ERROR(SSL, ERR_R_PASSED_NULL_PARAMETER);
   376      return 0;
