   382  int SSL_CTX_use_PrivateKey_ASN1(int type, SSL_CTX *ctx, const uint8_t *der,
   383                                  size_t der_len) {
   384    if (der_len > LONG_MAX) {
   385      OPENSSL_PUT_ERROR(SSL, ERR_R_OVERFLOW);
   386      return 0;
   387    }
   388
   389    const uint8_t *p = der;
   390    UniquePtr<EVP_PKEY> pkey(d2i_PrivateKey(type, NULL, &p, (long)der_len));
   391    if (!pkey || p != der + der_len) {
   392      OPENSSL_PUT_ERROR(SSL, ERR_R_ASN1_LIB);
   393      return 0;
   394    }
   395
   396    return SSL_CTX_use_PrivateKey(ctx, pkey.get());
   397  }
